#include <cmath>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <vector>

static const int MAX_R = 8;
static const int M_OUT = 18;
static const int N_SEG = 6;

static int64_t binom[30][30];
static int level_size[MAX_R + 1];
static int level_offset[MAX_R + 1];
static int total_states = 0;

// Per-state graph data
static std::vector<int> parent_state;
static std::vector<int> parent_edge;
static std::vector<int> children_table; // size: non_leaf_states * 18

static bool initialized = false;

static inline int rank_counts(const int* c, int k) {
    if (k == 0) return 0;
    int suffix = 0;
    int r = 0;
    // suffix_m = sum_{i=m}^{17} c[i]
    int suf[M_OUT + 1];
    suf[M_OUT] = 0;
    for (int i = M_OUT - 1; i >= 0; --i) {
        suf[i] = suf[i + 1] + c[i];
    }
    for (int m = 1; m < M_OUT; ++m) {
        int val = suf[m] + (M_OUT - 1 - m);
        int choose_k = M_OUT - m;
        r += (int)binom[val][choose_k];
    }
    return r;
}

static void gen_compositions(int idx, int rem, int* cur, int k, std::vector<int>& counts_flat) {
    if (idx == M_OUT - 1) {
        cur[idx] = rem;
        int r = rank_counts(cur, k);
        std::memcpy(&counts_flat[r * M_OUT], cur, M_OUT * sizeof(int));
        return;
    }
    for (int v = 0; v <= rem; ++v) {
        cur[idx] = v;
        gen_compositions(idx + 1, rem - v, cur, k, counts_flat);
    }
}

extern "C" {

void init_pomdp() {
    if (initialized) return;
    std::memset(binom, 0, sizeof(binom));
    for (int n = 0; n < 30; ++n) {
        binom[n][0] = 1;
        for (int k = 1; k <= n; ++k) {
            binom[n][k] = binom[n - 1][k - 1] + binom[n - 1][k];
        }
    }
    total_states = 0;
    for (int k = 0; k <= MAX_R; ++k) {
        level_offset[k] = total_states;
        level_size[k] = (int)binom[k + M_OUT - 1][M_OUT - 1];
        total_states += level_size[k];
    }

    parent_state.assign(total_states, -1);
    parent_edge.assign(total_states, -1);
    int non_leaf_total = level_offset[MAX_R];
    children_table.assign(non_leaf_total * M_OUT, -1);

    int cur[M_OUT];
    for (int k = 0; k < MAX_R; ++k) {
        std::vector<int> counts_flat(level_size[k] * M_OUT, 0);
        gen_compositions(0, k, cur, k, counts_flat);
        for (int r = 0; r < level_size[k]; ++r) {
            int u_id = level_offset[k] + r;
            int* c_ptr = &counts_flat[r * M_OUT];
            for (int j = 0; j < M_OUT; ++j) {
                c_ptr[j] += 1;
                int child_r = rank_counts(c_ptr, k + 1);
                c_ptr[j] -= 1;
                int v_id = level_offset[k + 1] + child_r;
                children_table[u_id * M_OUT + j] = v_id;
                if (parent_state[v_id] == -1) {
                    parent_state[v_id] = u_id;
                    parent_edge[v_id] = j;
                }
            }
        }
    }
    initialized = true;
}

// Compute likelihoods L[state * 6 + s] up to max_k
static void compute_likelihoods(const double* P, int max_k, std::vector<double>& L) {
    int n_st = level_offset[max_k] + level_size[max_k];
    L.resize(n_st * N_SEG);
    for (int s = 0; s < N_SEG; ++s) L[s] = 1.0;
    for (int k = 1; k <= max_k; ++k) {
        int start = level_offset[k];
        int end = start + level_size[k];
        for (int id = start; id < end; ++id) {
            int p = parent_state[id];
            int j = parent_edge[id];
            const double* lp = &L[p * N_SEG];
            double* lc = &L[id * N_SEG];
            for (int s = 0; s < N_SEG; ++s) {
                lc[s] = lp[s] * P[s * M_OUT + j];
            }
        }
    }
}

// Solve for a single applicant with belief b0[6], checks_remaining R <= 8, payoffs u[6], check_cost.
// Outputs root Q-values out_q[5]: [decline, approve, check0, check1, check2]
void solve_single(
    const double* P,       // [6 * 18]
    const double* b0,      // [6]
    const double* u_pay,   // [6]
    double check_cost,
    int R,
    double* out_q          // [5]
) {
    init_pomdp();
    std::vector<double> L;
    compute_likelihoods(P, R, L);

    double bu[N_SEG];
    for (int s = 0; s < N_SEG; ++s) bu[s] = b0[s] * u_pay[s];

    if (R == 0) {
        double app = 0.0;
        for (int s = 0; s < N_SEG; ++s) app += bu[s];
        out_q[0] = 0.0;
        out_q[1] = app;
        out_q[2] = -1e18;
        out_q[3] = -1e18;
        out_q[4] = -1e18;
        return;
    }

    std::vector<double> V_next(level_size[R]);
    // Base level R
    {
        int off = level_offset[R];
        int sz = level_size[R];
        for (int r = 0; r < sz; ++r) {
            const double* l = &L[(off + r) * N_SEG];
            double app = 0.0;
            for (int s = 0; s < N_SEG; ++s) app += bu[s] * l[s];
            V_next[r] = (app > 0.0) ? app : 0.0;
        }
    }

    std::vector<double> V_cur;
    for (int k = R - 1; k >= 0; --k) {
        int off = level_offset[k];
        int next_off = level_offset[k + 1];
        int sz = level_size[k];
        V_cur.resize(sz);
        for (int r = 0; r < sz; ++r) {
            int id = off + r;
            const double* l = &L[id * N_SEG];
            double z = 0.0;
            double app = 0.0;
            for (int s = 0; s < N_SEG; ++s) {
                z += b0[s] * l[s];
                app += bu[s] * l[s];
            }
            double best = (app > 0.0) ? app : 0.0;
            const int* ch = &children_table[id * M_OUT];
            double qc[3];
            for (int c = 0; c < 3; ++c) {
                double sum_v = 0.0;
                for (int y = 0; y < 6; ++y) {
                    sum_v += V_next[ch[c * 6 + y] - next_off];
                }
                qc[c] = -check_cost * z + sum_v;
                if (qc[c] > best) best = qc[c];
            }
            V_cur[r] = best;
            if (k == 0) {
                out_q[0] = 0.0;
                out_q[1] = app;
                out_q[2] = qc[0];
                out_q[3] = qc[1];
                out_q[4] = qc[2];
            }
        }
        V_next.swap(V_cur);
    }
}

// Given a model P_hat (used to choose actions) and P_true (used to evaluate),
// compute for all n_app applicants (priors[n_app * 6]) at depth R:
// out_v_opt[n_app]: optimal value under P_true
// out_v_eval[n_app]: achieved value of P_hat's policy under P_true
void eval_policy_all(
    const double* P_hat,    // [6 * 18]
    const double* P_true,   // [6 * 18]
    const double* priors,   // [n_app * 6]
    int n_app,
    const double* u_pay,    // [6]
    double check_cost,
    int R,
    double* out_v_opt,      // [n_app]
    double* out_v_eval      // [n_app]
) {
    init_pomdp();
    std::vector<double> L_hat, L_true;
    compute_likelihoods(P_hat, R, L_hat);
    compute_likelihoods(P_true, R, L_true);

    int n_st = level_offset[R] + level_size[R];
    std::vector<uint8_t> act(n_st); // 0=dec, 1=app, 2=c0, 3=c1, 4=c2
    std::vector<double> V_next(level_size[R]);
    std::vector<double> V_cur;

    for (int a = 0; a < n_app; ++a) {
        const double* b0 = &priors[a * N_SEG];
        double bu[N_SEG];
        for (int s = 0; s < N_SEG; ++s) bu[s] = b0[s] * u_pay[s];

        // 1. Optimal value under P_true
        {
            int off = level_offset[R];
            int sz = level_size[R];
            for (int r = 0; r < sz; ++r) {
                const double* l = &L_true[(off + r) * N_SEG];
                double app = 0.0;
                for (int s = 0; s < N_SEG; ++s) app += bu[s] * l[s];
                V_next[r] = (app > 0.0) ? app : 0.0;
            }
            for (int k = R - 1; k >= 0; --k) {
                int off_k = level_offset[k];
                int next_off = level_offset[k + 1];
                int sz_k = level_size[k];
                V_cur.resize(sz_k);
                for (int r = 0; r < sz_k; ++r) {
                    int id = off_k + r;
                    const double* l = &L_true[id * N_SEG];
                    double z = 0.0, app = 0.0;
                    for (int s = 0; s < N_SEG; ++s) {
                        z += b0[s] * l[s];
                        app += bu[s] * l[s];
                    }
                    double best = (app > 0.0) ? app : 0.0;
                    const int* ch = &children_table[id * M_OUT];
                    for (int c = 0; c < 3; ++c) {
                        double sum_v = 0.0;
                        for (int y = 0; y < 6; ++y) sum_v += V_next[ch[c * 6 + y] - next_off];
                        double qc = -check_cost * z + sum_v;
                        if (qc > best) best = qc;
                    }
                    V_cur[r] = best;
                }
                V_next.swap(V_cur);
            }
            out_v_opt[a] = V_next[0];
        }

        // 2. Policy actions under P_hat
        V_next.resize(level_size[R]);
        {
            int off = level_offset[R];
            int sz = level_size[R];
            for (int r = 0; r < sz; ++r) {
                int id = off + r;
                const double* l = &L_hat[id * N_SEG];
                double app = 0.0;
                for (int s = 0; s < N_SEG; ++s) app += bu[s] * l[s];
                if (app > 0.0) {
                    V_next[r] = app;
                    act[id] = 1;
                } else {
                    V_next[r] = 0.0;
                    act[id] = 0;
                }
            }
            for (int k = R - 1; k >= 0; --k) {
                int off_k = level_offset[k];
                int next_off = level_offset[k + 1];
                int sz_k = level_size[k];
                V_cur.resize(sz_k);
                for (int r = 0; r < sz_k; ++r) {
                    int id = off_k + r;
                    const double* l = &L_hat[id * N_SEG];
                    double z = 0.0, app = 0.0;
                    for (int s = 0; s < N_SEG; ++s) {
                        z += b0[s] * l[s];
                        app += bu[s] * l[s];
                    }
                    double best = 0.0;
                    uint8_t best_a = 0;
                    if (app > best) {
                        best = app;
                        best_a = 1;
                    }
                    const int* ch = &children_table[id * M_OUT];
                    for (int c = 0; c < 3; ++c) {
                        double sum_v = 0.0;
                        for (int y = 0; y < 6; ++y) sum_v += V_next[ch[c * 6 + y] - next_off];
                        double qc = -check_cost * z + sum_v;
                        if (qc > best) {
                            best = qc;
                            best_a = (uint8_t)(2 + c);
                        }
                    }
                    V_cur[r] = best;
                    act[id] = best_a;
                }
                V_next.swap(V_cur);
            }
        }

        // 3. Evaluate act[] under P_true
        V_next.resize(level_size[R]);
        {
            int off = level_offset[R];
            int sz = level_size[R];
            for (int r = 0; r < sz; ++r) {
                int id = off + r;
                if (act[id] == 1) {
                    const double* l = &L_true[id * N_SEG];
                    double app = 0.0;
                    for (int s = 0; s < N_SEG; ++s) app += bu[s] * l[s];
                    V_next[r] = app;
                } else {
                    V_next[r] = 0.0;
                }
            }
            for (int k = R - 1; k >= 0; --k) {
                int off_k = level_offset[k];
                int next_off = level_offset[k + 1];
                int sz_k = level_size[k];
                V_cur.resize(sz_k);
                for (int r = 0; r < sz_k; ++r) {
                    int id = off_k + r;
                    uint8_t a_id = act[id];
                    if (a_id == 0) {
                        V_cur[r] = 0.0;
                    } else if (a_id == 1) {
                        const double* l = &L_true[id * N_SEG];
                        double app = 0.0;
                        for (int s = 0; s < N_SEG; ++s) app += bu[s] * l[s];
                        V_cur[r] = app;
                    } else {
                        int c = (int)a_id - 2;
                        const double* l = &L_true[id * N_SEG];
                        double z = 0.0;
                        for (int s = 0; s < N_SEG; ++s) z += b0[s] * l[s];
                        const int* ch = &children_table[id * M_OUT];
                        double sum_v = 0.0;
                        for (int y = 0; y < 6; ++y) sum_v += V_next[ch[c * 6 + y] - next_off];
                        V_cur[r] = -check_cost * z + sum_v;
                    }
                }
                V_next.swap(V_cur);
            }
            out_v_eval[a] = V_next[0];
        }
    }
}

} // extern "C"

