extern "C" {

void init_bapomdp() {
    if (initialized) return;
    std::memset(binom, 0, sizeof(binom));
    for (int n = 0; n < 30; ++n) {
        binom[n][0] = 1;
        for (int k = 1; k <= n; ++k) binom[n][k] = binom[n - 1][k - 1] + binom[n - 1][k];
    }
    total_states = 0;
    for (int k = 0; k <= MAX_R; ++k) {
        level_offset[k] = total_states;
        level_size[k] = (int)binom[k + M_OUT - 1][M_OUT - 1];
        total_states += level_size[k];
    }
    parent_state.assign(total_states, -1);
    parent_edge.assign(total_states, -1);
    children_table.assign(level_offset[MAX_R] * M_OUT, -1);

    int cur[M_OUT];
    for (int k = 0; k < MAX_R; ++k) {
        std::vector<int> counts_flat(level_size[k] * M_OUT, 0);
        gen_compositions(0, k, cur, k, counts_flat);
        for (int r = 0; r < level_size[k]; ++r) {
            int u_id = level_offset[k] + r;
            int* c_ptr = &counts_flat[r * M_OUT];
            for (int j = 0; j < M_OUT; ++j) {
                c_ptr[j] += 1;
                int child_r = rank_counts(c_ptr, k + 1);
                c_ptr[j] -= 1;
                int v_id = level_offset[k + 1] + child_r;
                children_table[u_id * M_OUT + j] = v_id;
                if (parent_state[v_id] == -1) {
                    parent_state[v_id] = u_id;
                    parent_edge[v_id] = j;
                }
            }
        }
    }
    initialized = true;
}

// Coupled Bayes-Adaptive POMDP solver for M_ENS=64 models!
// P_ens: [64 * 6 * 18]
// w_init: [64 * 6], where w_init[m*6 + s] = model_prior_weight[m] * b0[s] * prod_{past obs on cur app} P_m(obs|s)
// u_pay: [6]
// R: checks remaining (0..8)
// out_q: [5] = expected coupled Q-values [decline, approve, bureau, income, bank] (normalized by sum(w_init))
void solve_bapomdp64(
    const double* P_ens,
    const double* w_init,
    const double* u_pay,
    double check_cost,
    int R,
    double* out_q
) {
    init_bapomdp();

    // Normalize w_init so numbers stay well-scaled
    double total_w = 0.0;
    for (int i = 0; i < M_ENS * N_SEG; ++i) total_w += w_init[i];
    double inv_w = (total_w > 0.0) ? (1.0 / total_w) : 1.0;

    // Pre-transpose P_ens into P_jm[18][6][64] for SIMD over m=0..63
    alignas(64) double P_jm[M_OUT][N_SEG][M_ENS];
    for (int m = 0; m < M_ENS; ++m) {
        for (int s = 0; s < N_SEG; ++s) {
            for (int j = 0; j < M_OUT; ++j) {
                P_jm[j][s][m] = P_ens[m * (N_SEG * M_OUT) + s * M_OUT + j];
            }
        }
    }

    alignas(64) double w0[N_SEG][M_ENS];
    for (int m = 0; m < M_ENS; ++m) {
        for (int s = 0; s < N_SEG; ++s) {
            w0[s][m] = w_init[m * N_SEG + s] * inv_w;
        }
    }

    if (R == 0) {
        double app_sum = 0.0;
        for (int s = 0; s < N_SEG; ++s) {
            double sw = 0.0;
            for (int m = 0; m < M_ENS; ++m) sw += w0[s][m];
            app_sum += u_pay[s] * sw;
        }
        out_q[0] = 0.0;
        out_q[1] = app_sum;
        out_q[2] = -1e18;
        out_q[3] = -1e18;
        out_q[4] = -1e18;
        return;
    }

    // Compute unnormalized joint weights W[state][6][64] up to level R?
    // Wait: 1.56M * 6 * 64 * 8 bytes = 4.8 GB, OR compute level-by-level?
    // Wait: we have 19 GB free RAM, or even cleaner: store W only for levels 0..R-1 (480k states = 1.47 GB!)
    // and compute level R on the fly from parent_state[id]!!
    // YES!! Computing level R on the fly uses ONLY 1.47 GB total AND saves memory bandwidth!!
    int non_leaf_n = level_offset[R]; // 480,700 for R=8!
    std::vector<double> W((size_t)non_leaf_n * N_SEG * M_ENS);

    for (int s = 0; s < N_SEG; ++s) {
        for (int m = 0; m < M_ENS; ++m) {
            W[s * M_ENS + m] = w0[s][m];
        }
    }

    for (int k = 1; k < R; ++k) {
        int start = level_offset[k], end = start + level_size[k];
        for (int id = start; id < end; ++id) {
            int p = parent_state[id];
            int j = parent_edge[id];
            const double* wp = &W[(size_t)p * (N_SEG * M_ENS)];
            double* wc = &W[(size_t)id * (N_SEG * M_ENS)];
            for (int s = 0; s < N_SEG; ++s) {
                const double* p_row = P_jm[j][s];
                const double* wp_s = &wp[s * M_ENS];
                double* wc_s = &wc[s * M_ENS];
                for (int m = 0; m < M_ENS; ++m) {
                    wc_s[m] = wp_s[m] * p_row[m];
                }
            }
        }
    }

    // Base level R: V_next has size level_size[R] * 64 (1,081,575 * 64 * 8 = 553 MB)
    std::vector<double> V_next((size_t)level_size[R] * M_ENS);
    {
        int off = level_offset[R], sz = level_size[R];
        alignas(64) double app_m[M_ENS];
        for (int r = 0; r < sz; ++r) {
            int id = off + r;
            int p = parent_state[id];
            int j = parent_edge[id];
            const double* wp = &W[(size_t)p * (N_SEG * M_ENS)];
            for (int m = 0; m < M_ENS; ++m) app_m[m] = 0.0;
            for (int s = 0; s < N_SEG; ++s) {
                double us = u_pay[s];
                const double* p_row = P_jm[j][s];
                const double* wp_s = &wp[s * M_ENS];
                for (int m = 0; m < M_ENS; ++m) {
                    app_m[m] += us * (wp_s[m] * p_row[m]);
                }
            }
            double sum_app = 0.0;
            for (int m = 0; m < M_ENS; ++m) sum_app += app_m[m];
            double* vn = &V_next[(size_t)r * M_ENS];
            if (sum_app > 0.0) {
                std::memcpy(vn, app_m, M_ENS * sizeof(double));
            } else {
                std::memset(vn, 0, M_ENS * sizeof(double));
            }
        }
    }

    // Backward induction k = R-1 down to 0
    std::vector<double> V_cur;
    alignas(64) double z_m[M_ENS];
    alignas(64) double app_m[M_ENS];
    alignas(64) double qc_m[3][M_ENS];

    for (int k = R - 1; k >= 0; --k) {
        int off_k = level_offset[k], next_off = level_offset[k + 1], sz_k = level_size[k];
        V_cur.resize((size_t)sz_k * M_ENS);
        for (int r = 0; r < sz_k; ++r) {
            int id = off_k + r;
            const double* wc = &W[(size_t)id * (N_SEG * M_ENS)];
            for (int m = 0; m < M_ENS; ++m) {
                z_m[m] = 0.0;
                app_m[m] = 0.0;
            }
            for (int s = 0; s < N_SEG; ++s) {
                double us = u_pay[s];
                const double* wc_s = &wc[s * M_ENS];
                for (int m = 0; m < M_ENS; ++m) {
                    double v = wc_s[m];
                    z_m[m] += v;
                    app_m[m] += us * v;
                }
            }
            double q_sum[5];
            q_sum[0] = 0.0;
            double sa = 0.0;
            for (int m = 0; m < M_ENS; ++m) sa += app_m[m];
            q_sum[1] = sa;

            const int* ch = &children_table[id * M_OUT];
            for (int c = 0; c < 3; ++c) {
                double* qcm = qc_m[c];
                for (int m = 0; m < M_ENS; ++m) qcm[m] = -check_cost * z_m[m];
                for (int y = 0; y < 6; ++y) {
                    const double* child_v = &V_next[(size_t)(ch[c * 6 + y] - next_off) * M_ENS];
                    for (int m = 0; m < M_ENS; ++m) {
                        qcm[m] += child_v[m];
                    }
                }
                double sc = 0.0;
                for (int m = 0; m < M_ENS; ++m) sc += qcm[m];
                q_sum[2 + c] = sc;
            }

            if (k == 0) {
                for (int a = 0; a < 5; ++a) out_q[a] = q_sum[a];
            }

            int best_a = 0;
            double best_v = 0.0;
            for (int a = 1; a < 5; ++a) {
                if (q_sum[a] > best_v) {
                    best_v = q_sum[a];
                    best_a = a;
                }
            }
            double* vc = &V_cur[(size_t)r * M_ENS];
            if (best_a == 0) {
                std::memset(vc, 0, M_ENS * sizeof(double));
            } else if (best_a == 1) {
                std::memcpy(vc, app_m, M_ENS * sizeof(double));
            } else {
                std::memcpy(vc, qc_m[best_a - 2], M_ENS * sizeof(double));
            }
        }
        V_next.swap(V_cur);
    }
}

